                O("Tạm dừng nhận đơn", 0, 1, 0, "Bạn giữ mọi người an toàn, khách thông cảm chờ điện sáng."))
        };
        foreach (var item in events)
            if (!db.RandomEvents.Any(e => e.Title == item.Title)) db.RandomEvents.Add(item);
        db.SaveChanges();
    }
    private static RandomEvent E(string title, string description, params EventOption[] options) => new() { Title = title, Description = description, EventType = EventType.Neighborhood, IsActive = true, Options = options.ToList() };
    private static EventOption O(string text, decimal money, int reputation, int viral, string result) => new() { Text = text, MoneyChange = money, ReputationChange = reputation, ViralChange = viral, ResultText = result };
}
